#!/usr/bin/env python3
"""Claude Code PreToolUse hook: Alembic migrations are autogenerated only."""

import json
import sys

PROTECTED_DIR = "/alembic/versions/"


def decide(decision, reason):
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": decision,
            "permissionDecisionReason": reason,
        }
    }, ensure_ascii=False))


def main():
    payload = json.load(sys.stdin)
    tool = payload.get("tool_name", "")
    path = payload.get("tool_input", {}).get("file_path", "")
    if PROTECTED_DIR not in path or not path.endswith(".py"):
        return
    if tool == "Write":
        decide("deny", "Migrations are never written by hand. Change the model in models/ and run "
                       "`make migration m=\"description\"` (alembic revision --autogenerate).")
    elif tool in ("Edit", "MultiEdit"):
        decide("ask", "Editing an autogenerated migration. Allowed only for what autogenerate can't do "
                      "(column rename, data migration). Confirm.")


if __name__ == "__main__":
    main()
